//import { toBool } from '../../util';
import aria from '../../aria-attributes';

const className = 'dialog-model';

function launchDialog(modal) {
    const dialogTopic = modal.getAttribute('data-topic');

    Array.from(modal.children).forEach((list) => {
        if (
            !list.dataset.modalcontent ||
            list.dataset.modalcontent === 'true'
        ) {
            const listOpenDialogButton = document.createElement('button'),
                listOpenDialogButtonSpan = document.createElement('span'),
                listOpenDialogButtonCredits = document.createElement('span'),
                listLabel = list.getAttribute('data-label'),
                customHeader = list.getAttribute('data-header'),
                listModuleCode = list.getAttribute('data-moduleCode'),
                listModuleCredits = list.getAttribute('data-moduleCredits'),
                listModuleCourseLoopURL = list.getAttribute(
                    'data-module-course-loop-url'
                ),
                listModuleYearLabel = list.getAttribute(
                    'data-module-year-label'
                ),
                dialogTopicP = document.createElement('p'),
                hr = document.createElement('hr');

            const listHeader = list.firstElementChild,
                listContent = list.lastElementChild;

            const dialog = document.createElement('dialog');
            dialog.classList.add('side-modal');

            let title,
                shortName = list.getAttribute('data-shortname'),
                label = listLabel || false,
                yearLabel = listModuleYearLabel ? listModuleYearLabel : false,
                moduleCode = listModuleCode
                    ? `Module Code: ${listModuleCode}`
                    : false,
                moduleCredits = listModuleCredits
                    ? `Credits: ${listModuleCredits}`
                    : false;

            const closeDialogButton = document.createElement('button'),
                closeDialogButtonSpan = document.createElement('span'),
                closeDialogButtonSpanText = document.createElement('span'),
                closeDialogForm = document.createElement('form');

            //dialog close button
            closeDialogForm.setAttribute('method', 'dialog');
            closeDialogButton.classList.add('side-modal__modal__close-btn');
            closeDialogButtonSpan.classList.add('fa-solid', 'fa-xmark');
            closeDialogButtonSpanText.classList.add('sr-only');
            closeDialogButtonSpanText.textContent = 'close';

            closeDialogButton.addEventListener('close', () => {});

            closeDialogButton.append(
                closeDialogButtonSpanText,
                closeDialogButtonSpan
            );

            closeDialogForm.appendChild(closeDialogButton);

            //open dialog button
            listOpenDialogButton.addEventListener('click', () => {
                dialog.showModal();
            });
            listOpenDialogButton.classList.add('modal__button');
            listOpenDialogButton.setAttribute('type', 'button');
            listOpenDialogButton.setAttribute(aria.label, 'Open dialog');

            listOpenDialogButtonSpan.classList.add('inline-text');
            listOpenDialogButton.appendChild(listOpenDialogButtonSpan);

            listOpenDialogButtonSpan.textContent =
                listHeader.childNodes[0].textContent;
            listHeader.remove();

            //open dialog button credits
            if (listModuleCredits) {
                listOpenDialogButtonCredits.classList.add(
                    'courses-v26__modules__credits'
                );
                listOpenDialogButtonCredits.textContent = listModuleCredits;
            }

            //Dialog module deatils wrapper
            const dialogModuleDetails = document.createElement('div');
            dialogModuleDetails.classList.add('courses-v26__modules-details');

            //Dialog Topic
            if (dialogTopic) {
                dialogTopicP.textContent = dialogTopic;

                dialog.appendChild(dialogTopicP);
            }

            //Dialog Heading
            if (customHeader) {
                title = customHeader;
            } else {
                title = listHeader.innerText;
            }

            if (yearLabel) {
                const yearLabelSpan = document.createElement('span');
                yearLabelSpan.classList.add(
                    'courses-v26__modules-details__year-label'
                );
                yearLabelSpan.textContent = yearLabel;
                dialog.appendChild(yearLabelSpan);
            }

            const dialogHeading = document.createElement('h3');
            dialogHeading.textContent = title;

            dialog.appendChild(dialogHeading);

            //Dailog Core label
            if (label || moduleCode || moduleCredits) {
                const coreLabelSpan = document.createElement('span');
                const moduleCreditCode = document.createElement('span');

                if (moduleCode && moduleCredits) {
                    moduleCreditCode.append(moduleCode, ' | ', moduleCredits);
                } else if (moduleCode) {
                    moduleCreditCode.appendChild(moduleCode);
                } else if (moduleCredits) {
                    moduleCreditCode.appendChild(moduleCredits);
                }
                coreLabelSpan.classList.add(
                    'courses-v26__modules-details__core-label'
                );

                const arrayOfLabels = label.split(';');
                const arrayOfLabelsFiltered = arrayOfLabels.filter(Boolean);

                if (arrayOfLabelsFiltered.length > 1) {
                    console.log('arrayOfLabelsFiltered', arrayOfLabelsFiltered);
                    const labelList = document.createElement('div');
                    labelList.classList.add(
                        'courses-v26__modules-details__core-label-list'
                    );

                    arrayOfLabelsFiltered.forEach((labelItem) => {
                        const labelListItemSpan =
                            document.createElement('span');
                        labelListItemSpan.classList.add(
                            'courses-v26__modules-details__core-label'
                        );
                        labelListItemSpan.textContent = labelItem.trim();
                        labelList.appendChild(labelListItemSpan);
                    });

                    dialogModuleDetails.appendChild(labelList);
                } else {
                    coreLabelSpan.textContent = label;
                    dialogModuleDetails.appendChild(coreLabelSpan);
                }

                dialogModuleDetails.append(moduleCreditCode);
                dialog.appendChild(dialogModuleDetails);
            }

            //dialog content append
            dialog.append(closeDialogForm, hr, listContent);

            //Dialog module course loop url
            if (listModuleCourseLoopURL) {
                const moduleCourseLoopURL = document.createElement('a');
                const moduleCourseLoopURLtextSpan =
                    document.createElement('span');
                const moduleCourseLoopTextIconSpan =
                    document.createElement('span');
                moduleCourseLoopTextIconSpan.classList.add(
                    'fa-thin',
                    'fa-arrow-right'
                );
                moduleCourseLoopURL.classList.add(
                    'primary-cta--bright',
                    'courses-v26__modules-course-loop-url'
                );
                moduleCourseLoopURLtextSpan.classList.add(
                    'courses-v26__modules-course-loop-url__text'
                );
                moduleCourseLoopURL.setAttribute(
                    'href',
                    listModuleCourseLoopURL
                );
                moduleCourseLoopURL.setAttribute('target', '_blank');
                moduleCourseLoopURL.setAttribute('rel', 'noopener noreferrer');
                moduleCourseLoopURLtextSpan.textContent = `View ${moduleCode} - ${
                    shortName ? shortName : listHeader.innerText
                }`;
                moduleCourseLoopURL.appendChild(moduleCourseLoopTextIconSpan);
                moduleCourseLoopURL.appendChild(moduleCourseLoopURLtextSpan);

                dialog.appendChild(moduleCourseLoopURL);
            }

            list.appendChild(listOpenDialogButton);

            if (moduleCredits) {
                list.appendChild(listOpenDialogButtonCredits);
            }

            list.appendChild(dialog);
        }
    });
}

export default {
    launchFn: launchDialog,
    launchQuery: `.${className}`,
};
